ado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1c03_intento_despachar_otp":true,"s1c03_webhook_n8n_otp":false,"s1c03_autenticacion_interna_invalida":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1c03_intento_despachar_otp":true,"s1c03_webhook_n8n_otp":true,"s1c03_autenticacion_interna_invalida":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s1c03_intento_despachar_otp":true,"s1c03_webhook_n8n_otp":true,"s1c03_autenticacion_interna_invalida":true},"esperado":true}]},{"tipo":"NUEVA","codigo":"S1-C04","clave":"s1c04_control","familia":"SECURITY","naturaleza":"CONDUCTA","clase":"BACKEND","alcance":"BACKEND","modo":"HEREDA","dueno":"TECNICO","titulo":"Bloquear aceptación de OTP por firma HMAC inválida","descripcion":"BLOQUEAR solo el intento de aceptar petición del webhook OTP cuando el resultado agregado de verificación de firma HMAC-SHA256 o su tiempo es inválido. El límite temporal se obtiene desde public.lf_global_config, AUTH/OTP_HMAC_TIMESTAMP_WINDOW_SECONDS. La condición requiere intento, contexto y violación; sin binding físico acreditado.","condicion":{"op":"y","izq":{"op":"y","izq":{"op":"=","izq":{"hecho":"s1c04_intento_aceptar_solicitud"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s1c04_webhook_otp_firmado"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s1c04_verificacion_firma_o_tiempo_invalida"},"der":{"lit":true}}},"efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/125","solicitante":"Cristhian / SECURITY 2026-11-23"},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s1c04_intento_aceptar_solicitud":false,"s1c04_webhook_otp_firmado":false,"s1c04_verificacion_firma_o_tiempo_invalida":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1c04_intento_aceptar_solicitud":false,"s1c04_webhook_otp_firmado":false,"s1c04_verificacion_firma_o_tiempo_invalida":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1c04_intento_aceptar_solicitud":false,"s1c04_webhook_otp_firmado":true,"s1c04_verificacion_firma_o_tiempo_invalida":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1c04_intento_aceptar_solicitud":false,"s1c04_webhook_otp_firmado":true,"s1c04_verificacion_firma_o_tiempo_invalida":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1c04_intento_aceptar_solicitud":true,"s1c04_webhook_otp_firmado":false,"s1c04_verificacion_firma_o_tiempo_invalida":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1c04_intento_aceptar_solicitud":true,"s1c04_webhook_otp_firmado":false,"s1c04_verificacion_firma_o_tiempo_invalida":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1c04_intento_aceptar_solicitud":true,"s1c04_webhook_otp_firmado":true,"s1c04_verificacion_firma_o_tiempo_invalida":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s1c04_intento_aceptar_solicitud":true,"s1c04_webhook_otp_firmado":true,"s1c04_verificacion_firma_o_tiempo_invalida":true},"esperado":true}]},{"tipo":"NUEVA","codigo":"S1-C05","clave":"s1c05_control","familia":"SECURITY","naturaleza":"CONDUCTA","clase":"BACKEND","alcance":"BACKEND","modo":"HEREDA","dueno":"TECNICO","titulo":"Bloquear despacho OTP con sesión inelegible","descripcion":"BLOQUEAR solo el intento de despachar OTP en contexto de sesión OTP cuando el backend comunica que la sesión no es elegible. La inelegibilidad agrupa sesión inexistente, OTP verificado, reenvíos agotados o cooldown activo; condición usa hecho agregado, no verifica esos campos individualmente ni acredita binding.","condicion":{"op":"y","izq":{"op":"y","izq":{"op":"=","izq":{"hecho":"s1c05_intento_despachar_otp"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s1c05_contexto_sesion_otp"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s1c05_sesion_inelegible"},"der":{"lit":true}}},"efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/126","solicitante":"Cristhian / SECURITY 2026-11-23"},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s1c05_intento_despachar_otp":false,"s1c05_contexto_sesion_otp":false,"s1c05_sesion_inelegible":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1c05_intento_despachar_otp":false,"s1c05_contexto_sesion_otp":false,"s1c05_sesion_inelegible":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1c05_intento_despachar_otp":false,"s1c05_contexto_sesion_otp":true,"s1c05_sesion_inelegible":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1c05_intento_despachar_otp":false,"s1c05_contexto_sesion_otp":true,"s1c05_sesion_inelegible":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1c05_intento_despachar_otp":true,"s1c05_contexto_sesion_otp":false,"s1c05_sesion_inelegible":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1c05_intento_despachar_otp":true,"s1c05_contexto_sesion_otp":false,"s1c05_sesion_inelegible":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1c05_intento_despachar_otp":true,"s1c05_contexto_sesion_otp":true,"s1c05_sesion_inelegible":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s1c05_intento_despachar_otp":true,"s1c05_contexto_sesion_otp":true,"s1c05_sesion_inelegible":true},"esperado":true}]},{"tipo":"NUEVA","codigo":"S1-C06","clave":"s1c06_control","familia":"SECURITY","naturaleza":"CONDUCTA","clase":"BACKEND","alcance":"BACKEND","modo":"HEREDA","dueno":"TECNICO","titulo":"Bloquear respuesta de error demasiado temprana","descripcion":"BLOQUEAR solo el intento de emitir una respuesta de error de validación de DNI, celular u OTP cuando su duración sea inferior al mínimo de public.lf_global_config, AUTH/ERROR_RESPONSE_MINIMUM_MS. La condición usa tres hechos lógicos sin umbral fijo ni binding del reloj acreditado.","condicion":{"op":"y","izq":{"op":"y","izq":{"op":"=","izq":{"hecho":"s1c06_intento_responder_error"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s1c06_validacion_dni_celular_otp"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s1c06_duracion_inferior_minimo"},"der":{"lit":true}}},"efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/130","solicitante":"Cristhian / SECURITY 2026-11-23"},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s1c06_intento_responder_error":false,"s1c06_validacion_dni_celular_otp":false,"s1c06_duracion_inferior_minimo":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1c06_intento_responder_error":false,"s1c06_validacion_dni_celular_otp":false,"s1c06_duracion_inferior_minimo":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1c06_intento_responder_error":false,"s1c06_validacion_dni_celular_otp":true,"s1c06_duracion_inferior_minimo":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1c06_intento_responder_error":false,"s1c06_validacion_dni_celular_otp":true,"s1c06_duracion_inferior_minimo":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1c06_intento_responder_error":true,"s1c06_validacion_dni_celular_otp":false,"s1c06_duracion_inferior_minimo":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1c06_intento_responder_error":true,"s1c06_validacion_dni_celular_otp":false,"s1c06_duracion_inferior_minimo":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1c06_intento_responder_error":true,"s1c06_validacion_dni_celular_otp":true,"s1c06_duracion_inferior_minimo":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s1c06_intento_responder_error":true,"s1c06_validacion_dni_celular_otp":true,"s1c06_duracion_inferior_minimo":true},"esperado":true}]}]'::jsonb) LOOP
 cd:=p->>'codigo';
 res:=lf_ops.nucleo_regla_proponer_v1(p,false);
 IF res->>'resultado'<>'EVALUADA_SIN_ESCRIBIR' OR (res->>'bloqueantes')::int<>0 THEN RAISE EXCEPTION 'SECURITY_PREFLIGHT % %',cd,res; END IF;
 res:=lf_ops.nucleo_regla_proponer_v1(p,true);
 IF res->>'resultado'<>'CANDIDATA' OR (res->>'version')::int<>1 THEN RAISE EXCEPTION 'SECURITY_CREATE % %',cd,res; END IF;
 IF (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1)<>8 OR
 (SELECT count(DISTINCT entrada::text) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1)<>8 THEN RAISE EXCEPTION 'SECURITY_TESTS_NOT_8_UNIQUE %',cd; END IF;
 IF lf_ops.nucleo_eval_v1((SELECT condicion FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1),
 (SELECT pp.entrada FROM lf_ops.nucleo_regla_pruebas pp WHERE pp.regla=cd AND pp.version=1 AND pp.esperado='false'::jsonb ORDER BY pp.n LIMIT 1))
 IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION 'SECURITY_INTENT_NEGATIVE %',cd; END IF;
 ev:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF ev->>'decision'='AUTO' THEN RAISE EXCEPTION 'SECURITY_NO_JUDGE_AUTO %',cd; END IF;
 hp:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 BEGIN
  PERFORM lf_ops.nucleo_juicio_registrar_v1(jsonb_build_object('regla',cd,'hash_evaluado',repeat('0',64),'veredicto','PASS','puntajes',
   jsonb_build_object('CAL_CLARIDAD',jsonb_build_object('puntaje',1),'CAL_ACCIONABLE',jsonb_build_object('puntaje',1),
    'CAL_ALCANCE',jsonb_build_object('puntaje',1),'SEM_NO_DUPLICA',jsonb_build_object('puntaje',1),
    'SEM_NO_CONTRADICE',jsonb_build_object('puntaje',1),'COH_TEXTO_CONDICION',jsonb_build_object('puntaje',1),
    'COH_EFECTO',jsonb_build_object('puntaje',1)),
   'juez','PG17_NEGATIVO_NO_REAL','modo','INDEPENDIENTE','revisor_es_productor',false,'llamadas_modelo',1,'evidencia_ref','PG17_HASH_NEGATIVE'));
  RAISE EXCEPTION 'SECURITY_BAD_HASH_ACCEPTED %',cd;
 EXCEPTION WHEN OTHERS THEN
  IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF;
 END;
 IF EXISTS(SELECT 1 FROM lf_ops.nucleo_juicios WHERE regla=cd AND version=1) THEN RAISE EXCEPTION 'SECURITY_FALSE_JUDGE_WRITTEN %',cd; END IF;
 RAISE NOTICE 'SECURITY_NEW_RESULT %',jsonb_build_object('regla',cd,'version',1,'nota',ev->'nota','decision',ev->>'decision',
 'hash_paquete',hp,'hash_version',(SELECT hash FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1),
 'pruebas_unicas',8,'legadas_fuente',1,'promocion','NO_PROMOVIDA');
 n:=n+1;
END LOOP;
IF n<>5 THEN RAISE EXCEPTION 'SECURITY_COUNT %',n; END IF;
